  7	import br.com.pousadamarealta.infrastructure.database.DatabaseConfig;
  8	import br.com.pousadamarealta.infrastructure.database.DatabaseInitializer;
  9	import com.fasterxml.jackson.databind.ObjectMapper;
 10	import com.fasterxml.jackson.databind.SerializationFeature;
 11	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 12	import io.javalin.Javalin;
 13	import io.javalin.json.JavalinJackson;
 14	
 15	import java.sql.Connection;
 16	
 17	public class Main {
 18	    public static void main(String[] args) {
 19	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 20	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 21	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 22	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 23	
 24	        DatabaseConfig databaseConfig = new DatabaseConfig(dbUrl, dbUser, dbPassword);
 25	
 26	        try (Connection connection = databaseConfig.getConnection()) {
 27	            DatabaseInitializer.initialize(connection);
 28	        } catch (Exception e) {
 29	            throw new RuntimeException("Erro ao inicializar banco de dados", e);
 30	        }
 31	
 32	        DocumentService documentService = new DocumentService();
 33	
 34	        RoomController roomController = new RoomController(databaseConfig);
 35	        ReservationController reservationController = new ReservationController(databaseConfig, documentService);
 36	        MessageController messageController = new MessageController(databaseConfig);
 37	        ReportController reportController = new ReportController(databaseConfig);
 38	
 39	        ObjectMapper objectMapper = new ObjectMapper();
 40	        objectMapper.registerModule(new JavaTimeModule());
 41	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 42	
 43	        Javalin app = Javalin.create(config -> {
 44	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 45	        }).start(port);
 46	
 47	        ErrorHandler.configure(app);
 48	
 49	        app.get("/rooms", roomController::getRooms);
 50	
 51	        app.post("/reservations", reservationController::createReservation);
 52	        app.get("/reservations/{id}", reservationController::getReservation);
 53	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 54	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 55	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 56	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 57	        app.get("/reservations/{id}/document", reservationController::getDocument);
 58	
 59	        app.get("/messages", messageController::getMessages);
 60	
 61	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 62	        app.get("/reports/revenue", reportController::getRevenueReport);
 63	
 64	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 65	            app.stop();
 66	            databaseConfig.close();
 67	        }));
 68	
 69	        System.out.println("Pousada Maré Alta - Sistema de Reservas iniciado na porta " + port);
 70	    }
 71	}
