102	    public void createReservation(Context ctx) {
103	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
104	
105	        validateRequest(request);
106	
107	        RatePlanType ratePlanType;
108	        try {
109	            ratePlanType = RatePlanType.valueOf(request.ratePlan());
110	        } catch (IllegalArgumentException e) {
111	            throw new InvalidRequestException("Plano de tarifa inválido");
112	        }
113	
114	        RatePlan.ReservationRequest ratePlanRequest = new RatePlan.ReservationRequest(
115	            request.roomNumber(),
116	            request.guestName(),
117	            request.guestEmail(),
118	            request.guestCpf(),
119	            request.checkIn(),
120	            request.checkOut(),
121	            request.guests(),
122	            request.companyCode()
123	        );
124	
125	        try (Connection connection = databaseConfig.getConnection()) {
126	            ReservationService reservationService = createReservationService(connection);
127	            Reservation reservation = reservationService.createReservation(ratePlanRequest, ratePlanType);
128	            ctx.status(201).json(ReservationResponse.from(reservation));
129	        } catch (InvalidRequestException | RoomNotFoundException |
130	                 RoomUnavailableException | CapacityExceededException e) {
131	            throw e;
132	        } catch (Exception e) {
133	            throw new RuntimeException("Erro ao processar requisição", e);
134	        }
135	    }
136	
137	    private void validateRequest(CreateReservationRequest request) {
138	        if (request.roomNumber() == null || request.roomNumber().isBlank()) {
139	            throw new InvalidRequestException("Número do quarto é obrigatório");
140	        }
141	        if (request.guestName() == null || request.guestName().isBlank()) {
142	            throw new InvalidRequestException("Nome do hóspede é obrigatório");
143	        }
144	        if (request.guestEmail() == null || request.guestEmail().isBlank()) {
145	            throw new InvalidRequestException("Email do hóspede é obrigatório");
146	        }
147	        if (request.guestCpf() == null || request.guestCpf().isBlank()) {
148	            throw new InvalidRequestException("CPF do hóspede é obrigatório");
149	        }
150	        if (request.checkIn() == null) {
151	            throw new InvalidRequestException("Data de entrada é obrigatória");
152	        }
153	        if (request.checkOut() == null) {
154	            throw new InvalidRequestException("Data de saída é obrigatória");
155	        }
156	        if (request.ratePlan() == null || request.ratePlan().isBlank()) {
157	            throw new InvalidRequestException("Plano de tarifa é obrigatório");
158	        }
159	    }
