200	    public void checkOut(Context ctx) {
201	        Long id = Long.parseLong(ctx.pathParam("id"));
202	        try (Connection connection = databaseConfig.getConnection()) {
203	            ReservationService reservationService = createReservationService(connection);
204	            RoomRepository roomRepository = new RoomRepository(connection);
205	            Reservation reservation = reservationService.checkOut(id);
206	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
207	            ctx.json(DocumentResponse.from(reservation, room));
208	        } catch (ReservationNotFoundException | OperationNotAllowedException e) {
209	            throw e;
210	        } catch (Exception e) {
211	            throw new RuntimeException("Erro ao processar requisição", e);
212	        }
213	    }
