228	    public void getDocument(Context ctx) {
229	        Long id = Long.parseLong(ctx.pathParam("id"));
230	        try (Connection connection = databaseConfig.getConnection()) {
231	            ReservationService reservationService = createReservationService(connection);
232	            RoomRepository roomRepository = new RoomRepository(connection);
233	            Reservation reservation = reservationService.getReservation(id);
234	
235	            if (reservation.getAmountPaid().compareTo(java.math.BigDecimal.ZERO) == 0) {
236	                throw new OperationNotAllowedException("Documento só disponível para reservas pagas");
237	            }
238	
239	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
240	            ctx.json(DocumentResponse.from(reservation, room));
241	        } catch (ReservationNotFoundException | OperationNotAllowedException e) {
242	            throw e;
243	        } catch (Exception e) {
244	            throw new RuntimeException("Erro ao processar requisição", e);
245	        }
246	    }
247	
248	    private ReservationService createReservationService(Connection connection) {
249	        ReservationRepository reservationRepository = new ReservationRepository(connection);
250	        RoomRepository roomRepository = new RoomRepository(connection);
251	        MessageRepository messageRepository = new MessageRepository(connection);
252	        MessageService messageService = new MessageService(messageRepository);
253	        return new ReservationService(reservationRepository, roomRepository, messageService, documentService);
254	    }
255	}
256	package br.com.pousadamarealta.api;
257	
258	import br.com.pousadamarealta.api.dto.ErrorResponse;
259	import br.com.pousadamarealta.domain.exception.*;
260	import io.javalin.Javalin;
261	import io.javalin.http.HttpStatus;
262	
263	public class ErrorHandler {
264	
265	    public static void configure(Javalin app) {
266	        app.exception(InvalidRequestException.class, (e, ctx) -> {
267	            ctx.status(HttpStatus.BAD_REQUEST)
268	               .json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
269	        });
270	
271	        app.exception(RoomNotFoundException.class, (e, ctx) -> {
272	            ctx.status(HttpStatus.NOT_FOUND)
273	               .json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
274	        });
275	
276	        app.exception(ReservationNotFoundException.class, (e, ctx) -> {
277	            ctx.status(HttpStatus.NOT_FOUND)
278	               .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
279	        });
280	
281	        app.exception(RoomUnavailableException.class, (e, ctx) -> {
282	            ctx.status(HttpStatus.CONFLICT)
283	               .json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
284	        });
285	
286	        app.exception(OperationNotAllowedException.class, (e, ctx) -> {
287	            ctx.status(HttpStatus.CONFLICT)
288	               .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
289	        });
290	
291	        app.exception(CapacityExceededException.class, (e, ctx) -> {
292	            ctx.status(HttpStatus.UNPROCESSABLE_CONTENT)
293	               .json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
294	        });
295	
296	        app.exception(NumberFormatException.class, (e, ctx) -> {
297	            ctx.status(HttpStatus.BAD_REQUEST)
298	               .json(new ErrorResponse("INVALID_REQUEST", "ID inválido"));
299	        });
300	
301	        app.exception(com.fasterxml.jackson.databind.JsonMappingException.class, (e, ctx) -> {
302	            ctx.status(HttpStatus.BAD_REQUEST)
303	               .json(new ErrorResponse("INVALID_REQUEST", "JSON inválido ou campos faltando"));
304	        });
305	
306	        app.exception(com.fasterxml.jackson.core.JsonProcessingException.class, (e, ctx) -> {
307	            ctx.status(HttpStatus.BAD_REQUEST)
308	               .json(new ErrorResponse("INVALID_REQUEST", "Corpo da requisição não é um JSON válido"));
309	        });
310	    }
311	}

