 10	import java.math.BigDecimal;
 11	import java.time.temporal.ChronoUnit;
 12	
 13	public class ReservationService {
 14	    private final ReservationRepository reservationRepository;
 15	    private final RoomRepository roomRepository;
 16	    private final MessageService messageService;
 17	    private final DocumentService documentService;
 18	
 19	    public ReservationService(
 20	        ReservationRepository reservationRepository,
 21	        RoomRepository roomRepository,
 22	        MessageService messageService,
 23	        DocumentService documentService
 24	    ) {
 25	        this.reservationRepository = reservationRepository;
 26	        this.roomRepository = roomRepository;
 27	        this.messageService = messageService;
 28	        this.documentService = documentService;
 29	    }
 30	
 31	    public Reservation createReservation(RatePlan.ReservationRequest request, RatePlanType ratePlanType) {
 32	        Room room = roomRepository.findByNumber(request.roomNumber())
 33	            .orElseThrow(() -> new RoomNotFoundException("Quarto não encontrado"));
 34	
 35	        validateBasicRules(request, room);
 36	
 37	        RatePlan ratePlan = RatePlanFactory.get(ratePlanType);
 38	        ratePlan.validate(request, room);
 39	
 40	        if (!reservationRepository.findConflicting(
 41	            request.roomNumber(),
 42	            request.checkIn(),
 43	            request.checkOut(),
 44	            null
 45	        ).isEmpty()) {
 46	            throw new RoomUnavailableException("Quarto não disponível para as datas solicitadas");
 47	        }
 48	
 49	        PriceCalculation price = ratePlan.calculatePrice(request, room);
 50	
 51	        Reservation reservation = new Reservation();
 52	        reservation.setRoomNumber(request.roomNumber());
 53	        reservation.setGuestName(request.guestName());
 54	        reservation.setGuestEmail(request.guestEmail());
 55	        reservation.setGuestCpf(request.guestCpf());
 56	        reservation.setCheckIn(request.checkIn());
 57	        reservation.setCheckOut(request.checkOut());
 58	        reservation.setGuests(request.guests());
 59	        reservation.setRatePlan(ratePlanType);
 60	        reservation.setCompanyCode(request.companyCode());
 61	        reservation.setNights((int) ChronoUnit.DAYS.between(request.checkIn(), request.checkOut()));
 62	        reservation.setSubtotal(price.getSubtotal());
 63	        reservation.setDiscount(price.getDiscount());
 64	        reservation.setTotal(price.getTotal());
 65	
 66	        return reservationRepository.save(reservation);
 67	    }
 68	
 69	    private void validateBasicRules(RatePlan.ReservationRequest request, Room room) {
 70	        if (request.guests() < 1) {
 71	            throw new InvalidRequestException("Número de hóspedes deve ser no mínimo 1");
 72	        }
 73	
 74	        if (request.guests() > room.getCapacity()) {
 75	            throw new CapacityExceededException("Número de hóspedes excede a capacidade do quarto");
 76	        }
 77	
 78	        if (!request.checkOut().isAfter(request.checkIn())) {
 79	            throw new InvalidRequestException("Data de saída deve ser posterior à data de entrada");
 80	        }
 81	    }
 82	
 83	    public Reservation confirmReservation(Long id) {
 84	        Reservation reservation = reservationRepository.findById(id)
 85	            .orElseThrow(() -> new ReservationNotFoundException("Reserva não encontrada"));
 86	
 87	        if (reservation.getStatus() != ReservationStatus.PENDING) {
 88	            throw new OperationNotAllowedException("Apenas reservas pendentes podem ser confirmadas");
 89	        }
 90	
 91	        reservation.setStatus(ReservationStatus.CONFIRMED);
 92	        reservation.setAmountPaid(reservation.getTotal());
 93	        reservationRepository.save(reservation);
 94	
 95	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
 96	        String emailBody = documentService.generateConfirmationEmail(reservation, room);
 97	        messageService.sendEmail(
 98	            reservation.getGuestEmail(),
 99	            "Reserva confirmada - Pousada Maré Alta",
100	            emailBody
101	        );
102	
103	        return reservation;
104	    }
105	
106	    public Reservation checkIn(Long id) {
107	        Reservation reservation = reservationRepository.findById(id)
108	            .orElseThrow(() -> new ReservationNotFoundException("Reserva não encontrada"));
109	
110	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
111	            throw new OperationNotAllowedException("Apenas reservas confirmadas podem fazer check-in");
112	        }
113	
114	        reservation.setStatus(ReservationStatus.CHECKED_IN);
115	        return reservationRepository.save(reservation);
116	    }
117	
118	    public Reservation checkOut(Long id) {
119	        Reservation reservation = reservationRepository.findById(id)
120	            .orElseThrow(() -> new ReservationNotFoundException("Reserva não encontrada"));
121	
122	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
123	            throw new OperationNotAllowedException("Apenas reservas com check-in podem fazer check-out");
124	        }
125	
126	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
127	        return reservationRepository.save(reservation);
128	    }
129	
130	    public Reservation cancelReservation(Long id) {
131	        Reservation reservation = reservationRepository.findById(id)
132	            .orElseThrow(() -> new ReservationNotFoundException("Reserva não encontrada"));
133	
134	        if (reservation.getStatus() != ReservationStatus.PENDING &&
135	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
136	            throw new OperationNotAllowedException("Apenas reservas pendentes ou confirmadas podem ser canceladas");
137	        }
138	
139	        RatePlan ratePlan = RatePlanFactory.get(reservation.getRatePlan());
140	        BigDecimal refund = ratePlan.calculateRefund(reservation);
141	
142	        reservation.setStatus(ReservationStatus.CANCELLED);
143	        reservation.setRefund(refund);
144	        return reservationRepository.save(reservation);
145	    }
146	
147	    public Reservation getReservation(Long id) {
148	        return reservationRepository.findById(id)
149	            .orElseThrow(() -> new ReservationNotFoundException("Reserva não encontrada"));
150	    }
151	}
