181	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
182	
183	    public String generateReceipt(Reservation reservation, Room room) {
184	        StringBuilder receipt = new StringBuilder();
185	
186	        receipt.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
187	        receipt.append("Hóspede: ").append(reservation.getGuestName())
188	               .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
189	        receipt.append("Quarto: ").append(reservation.getRoomNumber())
190	               .append(" (").append(room.getType().name()).append(")\n");
191	        receipt.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMATTER))
192	               .append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMATTER))
193	               .append(" | ").append(reservation.getNights())
194	               .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
195	        receipt.append("Diárias: ").append(CURRENCY_FORMAT.format(reservation.getSubtotal())).append("\n");
196	
197	        if (reservation.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
198	            receipt.append("Desconto: ").append(CURRENCY_FORMAT.format(reservation.getDiscount())).append("\n");
199	        }
200	
201	        receipt.append("Total: ").append(CURRENCY_FORMAT.format(reservation.getTotal()));
202	
203	        return receipt.toString();
204	    }
205	
206	    public String generateConfirmationEmail(Reservation reservation, Room room) {
207	        String receipt = generateReceipt(reservation, room);
208	
209	        return String.format("""
210	            Olá, %s!
211	
212	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
213	
214	            %s
215	
216	            A entrada é a partir das 14h, e a saída, até as 12h.
217	            Até breve!
218	            """, reservation.getGuestName(), receipt);
219	    }
220	
221	    private String formatCpf(String cpf) {
222	        if (cpf == null || cpf.length() != 11) {
223	            return cpf;
224	        }
225	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
226	               cpf.substring(6, 9) + "-" + cpf.substring(9);
227	    }
228	}

