  2	
  3	import br.com.pousadamarealta.domain.model.RatePlanType;
  4	import br.com.pousadamarealta.domain.model.Reservation;
  5	import br.com.pousadamarealta.domain.model.ReservationStatus;
  6	
  7	import java.sql.*;
  8	import java.time.LocalDate;
  9	import java.time.YearMonth;
 10	import java.util.ArrayList;
 11	import java.util.List;
 12	import java.util.Optional;
 13	
 14	public class ReservationRepository {
 15	    private final Connection connection;
 16	
 17	    public ReservationRepository(Connection connection) {
 18	        this.connection = connection;
 19	    }
 20	
 21	    public Reservation save(Reservation reservation) {
 22	        if (reservation.getId() == null) {
 23	            return insert(reservation);
 24	        } else {
 25	            return update(reservation);
 26	        }
 27	    }
 28	
 29	    private Reservation insert(Reservation reservation) {
 30	        String sql = """
 31	            INSERT INTO reservations (
 32	                room_number, guest_name, guest_email, guest_cpf,
 33	                check_in, check_out, guests, rate_plan, company_code,
 34	                nights, subtotal, discount, total, status, amount_paid, refund
 35	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 36	            RETURNING id
 37	            """;
 38	
 39	        try (PreparedStatement stmt = connection.prepareStatement(sql)) {
 40	            setReservationParameters(stmt, reservation);
 41	
 42	            try (ResultSet rs = stmt.executeQuery()) {
 43	                if (rs.next()) {
 44	                    reservation.setId(rs.getLong("id"));
 45	                }
 46	            }
 47	        } catch (SQLException e) {
 48	            throw new RuntimeException("Erro ao inserir reserva", e);
 49	        }
 50	
 51	        return reservation;
 52	    }
