 12	
 13	public class CorporateRatePlan implements RatePlan {
 14	    private static final Map<String, BigDecimal> COMPANY_DISCOUNTS = Map.of(
 15	        "TECNOSUL", new BigDecimal("0.12"),
 16	        "AGROVALE", new BigDecimal("0.18"),
 17	        "FARMAVIDA", new BigDecimal("0.25")
 18	    );
 19	
 20	    @Override
 21	    public void validate(ReservationRequest request, Room room) {
 22	        if (request.companyCode() == null || request.companyCode().trim().isEmpty()) {
 23	            throw new InvalidRequestException("Código da empresa é obrigatório para plano corporativo");
 24	        }
 25	
 26	        if (!COMPANY_DISCOUNTS.containsKey(request.companyCode())) {
 27	            throw new InvalidRequestException("Código da empresa inválido");
 28	        }
 29	    }
 30	
 31	    @Override
 32	    public PriceCalculation calculatePrice(ReservationRequest request, Room room) {
 33	        BigDecimal subtotal = BigDecimal.ZERO;
 34	        LocalDate current = request.checkIn();
 35	
 36	        while (current.isBefore(request.checkOut())) {
 37	            BigDecimal nightRate = SeasonCalculator.applySeasonRate(
 38	                room.getType().getNightlyRate(),
 39	                current
 40	            );
 41	            subtotal = subtotal.add(nightRate);
 42	            current = current.plusDays(1);
 43	        }
 44	
 45	        subtotal = subtotal.setScale(2, RoundingMode.HALF_EVEN);
 46	        BigDecimal discountRate = COMPANY_DISCOUNTS.get(request.companyCode());
 47	        BigDecimal discount = subtotal.multiply(discountRate).setScale(2, RoundingMode.HALF_EVEN);
 48	        BigDecimal total = subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
 49	
 50	        return new PriceCalculation(subtotal, discount, total);
 51	    }
 52	
 53	    @Override
 54	    public BigDecimal calculateRefund(Reservation reservation) {
 55	        return reservation.getAmountPaid();
 56	    }
 57	}
