203	public class SeasonCalculator {
204	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
205	
206	    public static boolean isHighSeason(LocalDate date) {
207	        Month month = date.getMonth();
208	        int day = date.getDayOfMonth();
209	
210	        if (month == Month.DECEMBER && day >= 15) {
211	            return true;
212	        }
